/* translated to C by Keith Richards-Dinger, 2010
   from Brendan Meade's Matlab code, whose original
   comments are reproduced below
   
   note that I store the elements of the strain tensor
   according to my convention in KRDOkada.h:
   (0 1 2
      3 4
        5)

function [S] = CalcTriStrains(sx, sy, sz, x, y, z, pr, ss, ts, ds)
% CalcTriStrains.m
%
% Calculates strains due to slip on a triangular dislocation in an
% elastic half space utilizing the symbolically differentiated
% displacement gradient tensor derived from the expressions for
% the displacements due to an angular dislocation in an elastic half
% space (Comninou and Dunders, 1975).
%
% Arguments
%  sx : x-coordinates of observation points
%  sy : y-coordinates of observation points
%  sz : z-coordinates of observation points
%  x  : x-coordinates of triangle vertices.
%  y  : y-coordinates of triangle vertices.
%  z  : z-coordinates of triangle vertices.
%  pr : Poisson's ratio
%  ss : strike slip displacement
%  ts : tensile slip displacement
%  ds : dip slip displacement
%
% Returns
%  S  : structure containing the strains (S.xx, S.yy, S.zz, S.xy, S.xz, S.yz)
%
% Implements algorithms described in the journal article:
% Meade, B. J. Algorithms for calculating displacements, 
% strains, and stresses for triangular dislocation elements
% in a uniform elastic half space
% Computers and Geosciences, submitted, 2006.
%
% Use at your own risk and please let me know of any bugs/errors.
%
% Copyright (c) 2006 Brendan Meade
% 
% Permission is hereby granted, free of charge, to any person obtaining a
% copy of this software and associated documentation files (the
% "Software"), to deal in the Software without restriction, including
% without limitation the rights to use, copy, modify, merge, publish,
% distribute, sublicense, and/or sell copies of the Software, and to permit
% persons to whom the Software is furnished to do so, subject to the
% following conditions:
% 
% The above copyright notice and this permission notice shall be included
% in all copies or substantial portions of the Software.
% 
% THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS
% OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF
% MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN
% NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM,
% DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR
% OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE
% USE OR OTHER DEALINGS IN THE SOFTWARE.

*/

#include "calcTriStrains.h"
#include "KRDOkada.h"


void calcTriStrains(double sx, double sy, double sz, 
                    double x[3], double y[3], double z[3], 
                    double pr, double ss, double ts, double ds, 
                    double S[6])
{
  double normVec[3], dx1[3], dx2[3], strikeVec[3], dipVec[3], slipComp[3], slipVec[3];
  double r[2], dip, beta;
  double ssVec[3], tsVec[3], dsVec[3];
  double lss, lts, lds;
  int ic, iTri;
  double s1[2], s2[2];
  double a[6], b[6];
  double bxx, byy, bzz, bxy, bxz, byz, g, e11n, e12n, e13n, e22n, e23n, e33n;
  double strike, segMapLength;
  
  /* Calculate the slip vector in XYZ coordinates */
  
  dx1[0] = x[1] - x[0];  dx1[1] = y[1] - y[0];  dx1[2] = z[1] - z[0];
  dx2[0] = x[2] - x[0];  dx2[1] = y[2] - y[0];  dx2[2] = z[2] - z[0];
  cross(dx1, dx2, normVec);
  normalize(normVec);

  if (normVec[2] < 0) /* Enforce clockwise circulation */
  {
     normVec[0] = -normVec[0]; normVec[1] = -normVec[1]; normVec[2] = -normVec[2];
     swap(&(x[1]), &(x[2]));
     swap(&(y[1]), &(y[2]));
     swap(&(z[1]), &(z[2]));
  }
  
  strikeVec[0] = -sin(atan2(normVec[1],normVec[0]));
  strikeVec[1] = cos(atan2(normVec[1],normVec[0]));
  strikeVec[2] = 0;
  cross(normVec, strikeVec, dipVec);
  slipComp[0] = ss;  slipComp[1] = ds; slipComp[2] = ts;
  slipVec[0] = strikeVec[0]*ss + dipVec[0]*ds + normVec[0]*ts;
  slipVec[1] = strikeVec[1]*ss + dipVec[1]*ds + normVec[1]*ts;
  slipVec[2] = strikeVec[2]*ss + dipVec[2]*ds + normVec[2]*ts;

  /* Solution vector */
  S[0] = 0; S[1] = 0; S[2] = 0; S[3] = 0; S[4] = 0; S[5] = 0;


  for (iTri=0; iTri<3; iTri++)
  {
     /* Calculate strike and dip of current leg */
     strike = 180/M_PI*(atan2(y[(iTri+1)%3]-y[iTri], x[(iTri+1)%3]-x[iTri]));
     segMapLength = sqrt((x[iTri]-x[(iTri+1)%3])*(x[iTri]-x[(iTri+1)%3]) + 
                         (y[iTri]-y[(iTri+1)%3])*(y[iTri]-y[(iTri+1)%3]));
     r[0] = x[(iTri+1)%3]-x[iTri]; r[1] = y[(iTri+1)%3]-y[iTri];
     rotateXyVec(&(r[0]), &(r[1]), -strike);
     dip = 180/M_PI*(atan2(z[(iTri+1)%3]-z[iTri], r[0]));

     if (dip >= 0)
     {
        beta = (M_PI/180)*(90-dip);
        if (beta > M_PI/2) beta = M_PI/2-beta;
     }
     else
     {
        beta = -(M_PI/180)*(90+dip);
        if (beta < -M_PI/2) beta = M_PI/2-fabs(beta);
     }

     ssVec[0] = cos(strike*M_PI/180); ssVec[1] = sin(strike*M_PI/180); ssVec[2] = 0;
     tsVec[0] = -sin(strike*M_PI/180); tsVec[1] = cos(strike*M_PI/180);  tsVec[2] = 0;
     cross(ssVec, tsVec, dsVec);
     lss = slipVec[0]*ssVec[0] + slipVec[1]*ssVec[1] + slipVec[2]*ssVec[2];
     lts = slipVec[0]*tsVec[0] + slipVec[1]*tsVec[1] + slipVec[2]*tsVec[2];
     lds = slipVec[0]*dsVec[0] + slipVec[1]*dsVec[1] + slipVec[2]*dsVec[2];

     if (fabs(beta) > 0.000001 && fabs(beta-M_PI) > 0.000001)
     {
        /* First angular dislocation */
        s1[0] = sx - x[iTri];  s1[1] = sy - y[iTri];
        rotateXyVec(&(s1[0]), &(s1[1]), -strike);
        advs(s1[0], s1[1], sz-z[iTri], z[iTri], beta, pr, lss, lts, lds, a);

        /* Second angular dislocation */
        s2[0] = sx - x[(iTri+1)%3]; s2[1] = sy - y[(iTri+1)%3];
        rotateXyVec(&(s2[0]), &(s2[1]), -strike);
        advs(s2[0], s2[1], sz-z[(iTri+1)%3], z[(iTri+1)%3], beta, pr, lss, lts, lds, b);

        /* Rotate tensors to correct for strike */
        bxx = a[0] - b[0];
        byy = a[3] - b[3];
        bzz = a[5] - b[5];
        bxy = a[1] - b[1];
        bxz = a[2] - b[2];
        byz = a[4] - b[4];

        g = (M_PI/180)*strike;
        e11n = (cos(g)*bxx-sin(g)*bxy)*cos(g)-(cos(g)*bxy-sin(g)*byy)*sin(g);
        e12n = (cos(g)*bxx-sin(g)*bxy)*sin(g)+(cos(g)*bxy-sin(g)*byy)*cos(g);
        e13n = cos(g)*bxz-sin(g)*byz;
        e22n = (sin(g)*bxx+cos(g)*bxy)*sin(g)+(sin(g)*bxy+cos(g)*byy)*cos(g);
        e23n = sin(g)*bxz+cos(g)*byz;
        e33n = bzz;

        /* % Add the strains from current leg */
        S[0] += e11n;
        S[3] += e22n;
        S[5] += e33n;
        S[1] += e12n;
        S[2] += e13n;
        S[4] += e23n;
     }
  } /* for (iTri=0; iTri<3; iTri++) */
}

/* Swap two values */
void swap(double *a, double *b)
{
  double temp;
  
  temp = *a;
  *a = *b;
  *b = temp;
  
  return;
}


/* Rotate a vector by an angle alpha */
void rotateXyVec(double *x, double *y, double alpha)
{
  double x0, y0;
  
  x0 = *x;  y0 = *y;
  
  alpha = (M_PI/180)*alpha;
  *x    = cos(alpha)*x0 - sin(alpha)*y0;
  *y    = sin(alpha)*x0 + cos(alpha)*y0;
  
  return;
}

